/-- `Measure.pi` transports heterogeneously across equality of the finite index
sets and heterogeneous equality of the coordinate measure families. -/
theorem measure_pi_heq {M : Type*}
    {Ω' : M → Type*} [∀ n, MeasurableSpace (Ω' n)]
    {I J : Finset M}
    {μI : (i : {i // i ∈ I}) → Measure (Ω' i.val)}
    {μJ : (j : {j // j ∈ J}) → Measure (Ω' j.val)}
    (h : I = J) (hμ : HEq μI μJ) :
    HEq (Measure.pi μI) (Measure.pi μJ) := by
  subst h
  have hμeq : μI = μJ := eq_of_heq hμ
  subst hμeq
  rfl

/-- [The pairwise solve factor](goal) converts off-diagonal residuals into coordinate-pair error;
it grows with [shift scale `M`](hyp:M) and shrinks with [separation margin `δ`](hyp:δ).

The factor six leaves room for centering and triangle inequalities while retaining the requested
specialization. -/
def pairwiseSolveFactor (M δ : ℝ) : ℝ :=
  6 * M / δ

