/-- For [a probability law `P`](hyp:P), the [bounded exponential-tilt score set](goal) consists
of L² classes that have an everywhere measurable, everywhere bounded,
mean-zero representative whose L² class is the specified vector. -/
def tiltScoreSet (P : Measure Z) [IsProbabilityMeasure P] : Set (Lp ℝ 2 P) :=
  {f | ∃ (g : Z → ℝ) (M : ℝ) (hg : MemLp g 2 P), Measurable g ∧
    (∀ z, |g z| ≤ M) ∧ (∫ z, g z ∂P) = 0 ∧ hg.toLp g = f}

/-- An in-class DGP's miss probability at its own ATE is dominated by the minimax miss. -/
theorem realV_le_minimaxMiss (P : VarConstr K) {n : ℕ} [NeZero K] {εg εm : ℝ}
    {m : Fin K × Bool → ℝ} {g : Bool → Fin K × Bool → ℝ}
    (hin : InClass (P.mhatV (K := K)) P.ghatV εg εm m g)
    (est : (Fin n → Obs (Fin K × Bool)) → ℝ) (s : ℝ) :
    (productLaw hin.valid n).real {x | s ≤ |est x - ate g|}
      ≤ minimaxMiss P.mhatV P.ghatV εg εm n est s := by
  simpa [nMiss] using
    nMiss_le_minimaxMiss (⟨(m, g), hin⟩ : InClassDGP (P.mhatV (K := K)) P.ghatV εg εm)
      (est := est) (s := s)

/-- An in-class DGP's miss probability at its own ATE is dominated by the minimax miss. -/
theorem real2_le_minimaxMiss (P : VarConstr2 K) {n : ℕ} [NeZero K] {εg εm : ℝ}
    {m : Fin K × Bool → ℝ} {g : Bool → Fin K × Bool → ℝ}
    (hin : InClass (P.mhat2 (K := K)) P.ghat2 εg εm m g)
    (est : (Fin n → Obs (Fin K × Bool)) → ℝ) (s : ℝ) :
    (productLaw hin.valid n).real {x | s ≤ |est x - ate g|}
      ≤ minimaxMiss P.mhat2 P.ghat2 εg εm n est s := by
  simpa [nMiss] using
    nMiss_le_minimaxMiss (⟨(m, g), hin⟩ : InClassDGP (P.mhat2 (K := K)) P.ghat2 εg εm)
      (est := est) (s := s)

/-- A specific in-class DGP's causal-centered miss probability is dominated by
the causal-centered minimax miss. -/
theorem nMissCausal_le_minimaxMissCausal {mhat : C → ℝ} {ghat : Bool → C → ℝ}
    {εg εm : ℝ} {n : ℕ} {est : (Fin n → Obs C) → ℝ} {s : ℝ}
    (p : InClassDGP mhat ghat εg εm) :
    (productLaw p.2.valid n).real
        {x | s ≤ |est x - causalATE (C := C) p.1.1 p.1.2|}
      ≤ minimaxMissCausal mhat ghat εg εm n est s :=
  le_ciSup (bddAbove_nMissCausal_range mhat ghat εg εm n est s) p

/-- A specific in-class DGP's miss probability is `≤ minimaxMiss`. -/
theorem nMiss_le_minimaxMiss [Nonempty C] {mhat : C → ℝ} {ghat : Bool → C → ℝ}
    {εg εm : ℝ} {n : ℕ} {est : (Fin n → Obs C) → ℝ} {s : ℝ}
    (p : InClassDGP mhat ghat εg εm) :
    nMiss p.2.valid n est s ≤ minimaxMiss mhat ghat εg εm n est s :=
  le_ciSup (bddAbove_nMiss_range mhat ghat εg εm n est s) p

