∀ {V : Type uV} [inst : Fintype V] [inst_1 : DecidableEq V] {X : V → Type uX} [inst_2 : (i : V) → MeasurableSpace (X i)] {μ : (i : V) → MeasureTheory.Measure (X i)} [inst_3 : ∀ (i : V), MeasureTheory.SigmaFinite (μ i)] {G : Causalean.Graph.DAG V} [inst_4 : (i : V) → TopologicalSpace (X i)] [∀ (i : V), BorelSpace (X i)] [∀ (i : V), CompactSpace (X i)] [inst_7 : ∀ (i : V), Nonempty (X i)] [inst_8 : ∀ (i : V), StandardBorelSpace (X i)] [∀ (i : V), (μ i).IsOpenPosMeasure] (M : Causalean.Graph.FiniteDensity.UniformlyPositiveContinuousFactorization G X μ) (i : V),
  have P := G.parents i;
