/-- For [a single-world intervention graph](hyp:G) and [a split node](hyp:v), the [bidirected-neighbor set](goal) consists exactly of the graph's observed nodes that are directly confounded with that node. -/
def bidirectedNeighbors (v : SWIGNode N) : Finset (SWIGNode N) :=
  G.observed.filter (fun w => G.directlyConfounded v w)

/-- For [a single-world intervention graph](hyp:G), [a set of active split nodes](hyp:active), and [two split nodes](hyp:u,v), the [induced edge relation](goal) holds exactly when [the original graph has the directed edge](step:1), [the first endpoint belongs to the active set](step:2), and [the second endpoint belongs to the active set](step:3). -/
def inducedEdge (active : Finset (SWIGNode N)) (u v : SWIGNode N) : Prop :=
  G.dag.edge u v ∧ u ∈ active ∧ v ∈ active

/-- For [a single-world intervention graph](hyp:G) and [a fixed intervention node in that graph](hyp:s), the [node-level canonical link](goal) is that node's random counterpart, with the membership certification omitted. -/
def iotaNode (G : SWIGGraph N) (s : {s // s ∈ G.fixed}) : SWIGNode N :=
  (G.iota s).1

/-- For [a real multivariate polynomial](hyp:p), its [real zero locus](goal) is the set of real
assignments at which the polynomial evaluates to zero. -/
def mvPolynomialZeroLocus (p : MvPolynomial σ ℝ) : Set (σ → ℝ) :=
  {x | MvPolynomial.eval x p = 0}

/-- The sum-coordinate form of a product domain requires the left and right restrictions of one
assignment to lie in their respective domains. -/
def sumProductDomain (D : Set (S → ℝ)) (E : Set (U → ℝ)) : Set ((S ⊕ U) → ℝ) :=
  {z | (z ∘ Sum.inl) ∈ D ∧ (z ∘ Sum.inr) ∈ E}

/-- [A bounded window](hyp:w) determines [its increasing list of active indices](goal). -/
def Window.indices {n : ℕ} (w : Window n) : List ℕ :=
  List.range' w.left (w.right - w.left)

/-- [A left endpoint](hyp:left) and [a deque](hyp:q) determine [the recorded front pops](goal). -/
def expiredFront (left : ℕ) (q : Deque) : List ℕ :=
  q.takeWhile (fun i => decide (i < left))

/-- [A raw-key list](hyp:keys), [a raw-key score](hyp:score), and [an out-of-bounds fallback
score](hyp:fallback) determine [the total position stream used by the generic deque](goal).  The
fallback is never observed at a valid position. -/
def keyedStream (keys : List ι) (score : ι → α) (fallback : α) : Stream α :=
  { length := keys.length
    value := fun i => (keys[i]?).map score |>.getD fallback }

/-- For [a measure on the real line](hyp:ν), [support on the unit interval](goal) means that the complement of the closed interval from −1 to 1 has measure zero. -/
def IsSupportedOnUnitInterval (ν : Measure ℝ) : Prop :=
  ν (symmUnitIntervalᶜ) = 0

/-- For [a Borel measure on the real line](hyp:ν), [symmetry about zero](goal) means that reflecting every point through zero leaves the measure unchanged. -/
def IsSymmetric (ν : Measure ℝ) : Prop :=
  Measure.map (fun x : ℝ => -x) ν = ν

/-- [The normalized cosine mode](goal) with [index](hyp:j) at [position](hyp:x)
is one for the zero mode and square root of two times cosine of π times index
times position otherwise. -/
def cosineBasis (j : ℕ) (x : ℝ) : ℝ :=
  if j = 0 then 1 else Real.sqrt 2 * Real.cos (Real.pi * (j : ℝ) * x)

/-- [The even periodic extension](goal) of an [interval function](hyp:f)
at an [angle](hyp:t) evaluates that function at the folded position. -/
def evenExtension (f : ℝ → ℝ) (t : ℝ) : ℝ := f (fold t)

/-- [Uniform probability on the unit interval](goal) is Lebesgue measure restricted
to the closed interval from zero to one. -/
def uniformMeasure : Measure ℝ := volume.restrict (Set.Icc 0 1)

/-- [An angle vector](hyp:x) determines [its coordinatewise cosine point](goal).
[The point](step:1) applies cosine in every coordinate. -/
def cosPoint (x : ι → ℝ) : ι → ℝ := fun i => Real.cos (x i)

/-- The normalized cube [is the set of coordinate vectors with every entry between minus one and one](goal).
[This set](step:1) is specified coordinatewise. -/
def cube : Set (ι → ℝ) := {x | ∀ i, x i ∈ Set.Icc (-1 : ℝ) 1}

/-- [A coordinate-specific degree map](hyp:d) determines [the uniform interpolation degree](goal).
[The degree](step:1) is the sum of the coordinatewise Jackson degree bounds. -/
def interpolationDegree (d : ι → ℕ) : ℕ := ∑ i, 2 * (d i - 1)

/-- The [triangular sequence](goal) of [order N](hyp:N) at [an integer frequency j](hyp:j) is [N
minus the absolute value of j when that is nonnegative, and zero otherwise](step:1). -/
def triangle (N : ℕ) (j : ℤ) : ℝ := ((N - j.natAbs : ℕ) : ℝ)

