/-- [The closed exterior slab](goal) of the normalized cube's left collar in
[dimension d](hyp:d), for [derivative order m](hyp:m) and [coordinate i](hyp:i),
is the part of that collar whose i-th coordinate is at most −1, that is, on or
beyond the left face. -/
def leftClosedExteriorCollar (d m : ℕ) (i : Fin d) : Set (Fin d → ℝ) :=
  leftCubeCollar d m i ∩ {x | x i ≤ -1}

/-- [The open exterior collar](goal) at the left face of the normalized cube in
[dimension d](hyp:d), for [derivative order m](hyp:m) and [coordinate i](hyp:i),
is the set of points whose i-th coordinate lies strictly between
−1 − 1/(m + 1) and −1 and whose other coordinates lie strictly between −1 and
1. -/
def leftOpenCubeCollar (d m : ℕ) (i : Fin d) : Set (Fin d → ℝ) :=
  {x | ∀ j : Fin d,
    if j = i then x j ∈ Set.Ioo (-1 - (1 : ℝ) / ((m : ℝ) + 1)) (-1)
    else x j ∈ Set.Ioo (-1 : ℝ) 1}

/-- In [fixed dimensions](hyp:t,c), [the closed mixed support](goal) is
[the tangent coordinate cube times the complementary radius-two ball](step:1). -/
def mixedSupport (t c : ℕ) : Set (EuclideanSpace ℝ (Fin t ⊕ Fin c)) :=
  {x | (∀ i : Fin t, |x (Sum.inl i)| ≤ 1) ∧
    ‖(WithLp.toLp 2 (fun i : Fin c => x (Sum.inr i)) : EuclideanSpace ℝ (Fin c))‖ ≤ 2}

/-- [The closed coordinate box](goal) with [lower corner lo and upper corner
hi](hyp:lo,hi) is the set of points whose i-th coordinate lies in
`[lo i, hi i]` for every i. -/
def rectBox {d : ℕ} (lo hi : Fin d → ℝ) : Set (Fin d → ℝ) :=
  {x | ∀ i, x i ∈ Set.Icc (lo i) (hi i)}

/-- [The open coordinate box](goal) with [corners lo and hi](hyp:lo,hi) consists of
the points lying strictly between lo_i and hi_i in every coordinate i. -/
def rectOpenBox {d : ℕ} (lo hi : Fin d → ℝ) : Set (Fin d → ℝ) :=
  {x | ∀ i, lo i < x i ∧ x i < hi i}

/-- [The scaled support](goal) of [a set](hyp:K) at [a bandwidth and center](hyp:h,z)
is [its inverse image under translation and inverse dilation](step:1). -/
def scaledSupport (h : ℝ) (z : E) (K : Set E) : Set E :=
  {x | h⁻¹ • (x - z) ∈ K}

/-- The [closed coordinate cube](goal) with [centre a](hyp:a) and [side length h](hyp:h) is [the
set of points each of whose coordinates is within h / 2 of the matching coordinate of a](step:1).
-/
def centeredCube {d : ℕ} (a : EuclideanSpace ℝ (Fin d)) (h : ℝ) :
    Set (EuclideanSpace ℝ (Fin d)) := {x | ∀ i, |x i - a i| ≤ h / 2}

/-- The multiplicity of coordinate `i` in a sequence of coordinate directions. -/
def coordCount {d m : ℕ} (f : Fin m → Fin d) (i : Fin d) : ℕ :=
  (Finset.univ.filter (fun k => f k = i)).card

/-- [A finite dimension](hyp:d) determines [the open normalized cube](goal), whose coordinates lie strictly between minus one and one. -/
def openCube (d : ℕ) : Set (Fin d → ℝ) :=
  Set.univ.pi (fun _ => Set.Ioo (-1 : ℝ) 1)

/-- The unit cube consists of points whose coordinates lie in `[0,1]`. -/
def unitCube (d : ℕ) : Set (Fin d → ℝ) :=
  Set.univ.pi (fun _ => Set.Icc (0 : ℝ) 1)

/-- For [a complex-valued function](hyp:f), [a complex center](hyp:c), and [a real radius](hyp:R), [the interior-zero set](goal) consists exactly of the complex numbers that are zeros of the function and lie strictly inside the open disk with that center and radius.

This set comprises exactly the zeros of a complex-valued function that lie strictly inside a
given open disk. -/
def interiorZeros (f : ℂ → ℂ) (c : ℂ) (R : ℝ) : Set ℂ :=
  {z | z ∈ ball c R ∧ f z = 0}

/-- For [a complex-valued function](hyp:f), [a complex center](hyp:c), and [a real radius](hyp:R), [the zero-multiplicity count](goal) is the sum of the analytic multiplicities of all zeros of the function lying strictly inside the open disk with that center and radius, with the standard totalized finite sum used when the support is not finite.

This count adds the analytic multiplicity of every zero strictly inside a given open disk;
outside finite-support settings it uses the standard totalized finite sum. -/
def zeroMultiplicityCount (f : ℂ → ℂ) (c : ℂ) (R : ℝ) : ℕ :=
  ∑ᶠ z : ℂ, if z ∈ ball c R then analyticOrderNatAt f z else 0

