/-- The [region associated with a radial side](goal) is [the closed interior of the unit circle
for the inside side](step:1), and [the strict exterior of the unit circle for the outside side](step:2). -/
def CircleSide.region : CircleSide → Set Plane
  | .inside => {z | radialOffset z ≤ 0}
  | .outside => {z | 0 < radialOffset z}

/-- For [a finite set of planar sites](hyp:sites) and [a real radius](hyp:r), the [property of covering the unit circle](goal) means that every point of the unit circle belongs to an open ball of radius $r$ centred at one of the sites. -/
def CoversUnitCircle (sites : Finset Plane) (r : ℝ) : Prop :=
  unitCircle ⊆ ⋃ x ∈ (sites : Set Plane), ball x r

/-- For [a finite set of planar sites](hyp:sites) and [a real separation scale](hyp:r), the [property of being a maximal separated set on the unit circle](goal) means that the sites lie on the unit circle, are separated by at least that scale, and are maximal among all sets with both properties. -/
def IsMaximalSeparated (sites : Finset Plane) (r : ℝ) : Prop :=
  Maximal (fun s : Set Plane => s ⊆ unitCircle ∧ IsSeparatedAtLeast r s) (sites : Set Plane)

/-- For [a real separation scale](hyp:r) and [a set of planar points](hyp:s), the [property of being separated at least at that scale](goal) means that every two distinct points in the set are at distance at least the separation scale. -/
def IsSeparatedAtLeast (r : ℝ) (s : Set Plane) : Prop :=
  s.Pairwise fun x y => r ≤ dist x y

/-- For [a real exponent](hyp:κ) and [a real tube width](hyp:δ), the [weighted annular normalizer](goal) is the two-dimensional Lebesgue integral of the radial power weight with that exponent over the annular tube of that width. The integral is the real-valued Bochner integral, which is zero when the weight is not integrable there; the results below use it for exponents above two, where it is integrable. -/
def annularNormalizer (κ δ : ℝ) : ℝ :=
  ∫ z in annularTube δ, powerWeight κ z ∂volume

/-- For [a real exponent](hyp:κ), [a choice of the inside or outside of the unit circle](hyp:side), [a planar centre](hyp:x), and [a real radius](hyp:h), the [weighted side-ball mass](goal) is the two-dimensional Lebesgue integral of the radial power weight with that exponent over the corresponding one-sided open ball. The integral is the real-valued Bochner integral, which is zero when the weight is not integrable there; the results below use it for exponents above two, where it is integrable. -/
def sideBallMass (κ : ℝ) (side : CircleSide) (x : Plane) (h : ℝ) : ℝ :=
  ∫ z in sideBall side x h, powerWeight κ z ∂volume

/-- A complex right eigenvalue of a real square matrix. -/
def ComplexMatrixEigenvalue {n : ℕ} (A : RectMatrix n n) (z : ℂ) : Prop :=
  ∃ v : Fin n → ℂ, v ≠ 0 ∧ ∀ i, ∑ j, (A i j : ℂ) * v j = z * v i

/-- The [angular unitary prefactor](goal) in [dimension](hyp:p) is the negative half-dimensional
power of two pi. -/
def angularPrefactor (p : ℕ) : ℝ := (2 * Real.pi) ^ (-(p : ℝ) / 2)

/-- The [complexification](goal) of a [real spatial function](hyp:G) is its pointwise inclusion
into the complex numbers. -/
def complexify {p : ℕ} (G : Space p → ℝ) : Space p → ℂ := fun x => (G x : ℂ)

/-- [A Gaussian scale parameter](hyp:σ) and [a complex frequency profile](hyp:F) determine [the inverse-Gaussian frequency multiplier](goal) [by multiplication with the reciprocal Gaussian characteristic function](step:1). -/
def inverseGaussian (σ : ℝ) (F : ℝ → ℂ) : ℝ → ℂ :=
  fun ξ => F ξ * (Real.exp (σ ^ 2 * (2 * Real.pi * ξ) ^ 2 / 2) : ℂ)

/-- The [zero-order angular energy](goal) of a [function](hyp:G) is the squared energy of its
normalized angular Fourier integral. -/
def zeroEnergy {p : ℕ} (G : Space p → ℂ) : ℝ≥0∞ := l2Energy (angularFourier G)

/-- For [two certified real numbers](hyp:x,y), [their certified difference](goal) is their certified sum after negating the second certificate; it therefore denotes the first named real number minus the second.

Subtracting certified names adds the first enclosure to the negation of the second. -/
def sub (x y : CertifiedReal) : CertifiedReal := add x (neg y)

/-- For [a sequence of complex rational rectangles](hyp:nodes) and [a mesh size](hyp:n), [the trapezoidal enclosure](goal) is the unscaled trapezoidal rectangle sum multiplied by $1/(2n)$. It is meaningful for positive mesh size, as required by the integral enclosure built from it; at mesh size zero the scale factor is zero by the division convention. -/
def trapezoidEnclosure (nodes : ℕ → ComplexRatInterval) (n : ℕ) : ComplexRatInterval :=
  ComplexRatInterval.smulRat (1 / (2 * n : ℚ)) (trapezoidSum nodes n)

/-- Given [a rational rectangle](hyp:I) and [a complex number](hyp:z), [rectangle membership](goal) means that both the real and imaginary coordinates of the number lie in their respective rational intervals. -/
def Contains (I : ComplexRatInterval) (z : ℂ) : Prop :=
  I.re.Contains z.re ∧ I.im.Contains z.im

/-- Given [two rational rectangles in the complex plane](hyp:I,J), [the refinement relation](goal) holds exactly when each coordinate interval of the first is contained in the corresponding coordinate interval of the second. -/
def Subinterval (I J : ComplexRatInterval) : Prop :=
  I.re.Subinterval J.re ∧ I.im.Subinterval J.im

/-- For [two rational rectangles in the complex plane](hyp:I,J), [their sum rectangle](goal) is obtained by adding their real-coordinate intervals and their imaginary-coordinate intervals separately. -/
def add (I J : ComplexRatInterval) : ComplexRatInterval :=
  ⟨I.re.add J.re, I.im.add J.im⟩

/-- For [a rational rectangle in the complex plane](hyp:I), [a rational error allowance](hyp:e), and [the condition that this allowance is nonnegative](hyp:he), [the expanded rectangle](goal) widens each coordinate interval by that allowance. -/
def expand (I : ComplexRatInterval) (e : ℚ) (he : 0 ≤ e) : ComplexRatInterval :=
  ⟨I.re.expand e he, I.im.expand e he⟩

/-- For [a rational scalar](hyp:q) and [a rational rectangle in the complex plane](hyp:I), [the scalar-multiple rectangle](goal) is obtained by multiplying each coordinate interval by that scalar. -/
def smulRat (q : ℚ) (I : ComplexRatInterval) : ComplexRatInterval :=
  ⟨(RatInterval.point q).mul I.re, (RatInterval.point q).mul I.im⟩

/-- An interval matrix contains a real matrix when it contains every entry. -/
def ContainsMatrix {ι κ : Type*} (I : IntervalMatrix ι κ) (A : Matrix ι κ ℝ) : Prop :=
  ∀ i j, (I i j).Contains (A i j)

/-- An interval vector contains a real vector when it contains every coordinate. -/
def ContainsVector {ι : Type*} (I : IntervalVector ι) (x : ι → ℝ) : Prop :=
  ∀ i, (I i).Contains (x i)

/-- For [a certified complex name](hyp:z) and [a requested positive rational tolerance](hyp:ε), [the modulus precision](goal) is the maximum of a fuel level that refines the input rectangle to a tolerance determined by its initial magnitude bound and an explicit Newton-iteration fuel bound. -/
def normPrecision (z : CertifiedComplex) (ε : PosRat) : ℕ :=
  let M := ComplexRatInterval.maxAbs (z.approx 0)
  let δ : PosRat :=
    ⟨ε.1 ^ 2 / (16 * (M + 1)), by
      have hM : 0 ≤ M := by
        exact le_max_of_le_left ((abs_nonneg _).trans (le_max_left _ _))
      exact div_pos (sq_pos_of_pos ε.2) (by nlinarith)⟩
  max (z.modulus δ) (64 * (ε.1.den + 1) * (M.num.natAbs + 2) ^ 2)

/-- Given [a numerator rectangle](hyp:I), [a denominator rectangle](hyp:J), and [evidence that the denominator's squared-modulus interval excludes zero](hyp:hJ), the [guarded quotient rectangle](goal) is [the product of the numerator rectangle and the denominator's conjugate](step:1), with both resulting coordinate intervals divided by the denominator's squared-modulus interval. -/
def div (I J : ComplexRatInterval) (hJ : (normSq J).AwayFromZero) : ComplexRatInterval :=
  let numerator := mul I (conj J)
  ⟨numerator.re.div (normSq J) hJ, numerator.im.div (normSq J) hJ⟩

/-- Given [a rational complex rectangle](hyp:I), its [squared-modulus interval](goal) is the sum of the sign-aware squares of its real and imaginary coordinate intervals. -/
def normSq (I : ComplexRatInterval) : RatInterval :=
  (RatInterval.sq I.re).add (RatInterval.sq I.im)

/-- Given [a rational real coordinate](hyp:x) and [a rational imaginary coordinate](hyp:y), the [complex point rectangle](goal) is the zero-width rectangle containing $x+iy$. -/
def point (x y : ℚ) : ComplexRatInterval :=
  ⟨RatInterval.point x, RatInterval.point y⟩

/-- Given [two rational complex rectangles](hyp:I,J), their [coordinatewise tightening](goal) is formed by tightening the real coordinate intervals and tightening the imaginary coordinate intervals. -/
def tighten (I J : ComplexRatInterval) : ComplexRatInterval :=
  ⟨I.re.tighten J.re, I.im.tighten J.im⟩

/-- Given [a certified complex number](hyp:z) and [a natural-number stage index](hyp:n), the [complex-exponential stage rectangle](goal) evaluates the complex exponential on that stage's input rectangle using that stage's fuel. -/
def complexExpStage (z : CertifiedComplex) (n : ℕ) : ComplexRatInterval :=
  complexExp (complexExpStageInput z n) (complexExpStageFuel z n)

/-- Given [a certified complex number](hyp:z) and [a natural-number stage index](hyp:n), the [complex-exponential stage input rectangle](goal) is the input's approximation at the precision required by that stage's input tolerance. -/
def complexExpStageInput (z : CertifiedComplex) (n : ℕ) : ComplexRatInterval :=
  z.approx (z.modulus (complexExpInputTolerance z n))

/-- Given [a natural-number stage index](hyp:n), the [complex-exponential stage tolerance](goal) is the positive rational number $1/(n+1)$. -/
def complexExpStageTolerance (n : ℕ) : PosRat :=
  ⟨1 / (n + 1 : ℚ), by positivity⟩

entries.doc:
Every scheduled stage has width at most its reciprocal stage tolerance;
the proof combines input refinement, scalar Taylor convergence, magnitude
amplification, and explicit rectangle-product propagation.

entries.source:
/-- Given [a rational argument](hyp:q) and [a natural-number fuel level](hyp:fuel), the [cosine remainder scale](goal) is $|q|^{2f+2}/(2f+2)!$. -/
def cosError (q : ℚ) (fuel : ℕ) : ℚ :=
  |q| ^ (2 * fuel + 2) / ((2 * fuel + 2).factorial : ℚ)

/-- Given [a rational argument](hyp:q) and [a natural-number fuel level](hyp:fuel), the [sine remainder scale](goal) is $|q|^{2f+3}/(2f+3)!$. -/
def sinError (q : ℚ) (fuel : ℕ) : ℚ :=
  |q| ^ (2 * fuel + 3) / ((2 * fuel + 3).factorial : ℚ)

/-- Given [a rational radius](hyp:radius) and [a positive rational target width](hyp:target), the [circle input precision](goal) is the π-approximation precision selected for their internal circle tolerance. -/
def circleInputPrecision (radius : ℚ) (target : PosRat) : ℕ :=
  Transcendental.piPrecision (circleInnerTolerance radius target)

/-- Given [a rational radius](hyp:radius), [a contour schedule](hyp:schedule), and [a natural-number endpoint index](hyp:k), the [scheduled circle-node rectangle](goal) is the rational-interval evaluation of $r\exp(2πik/m)$ using that schedule's angle enclosure and fuel. -/
def circleNode (radius : ℚ) (schedule : Schedule) (k : ℕ) : ComplexRatInterval :=
  (Transcendental.complexExp (circleAngle schedule k) schedule.fuel).smulRat radius

/-- For [a nonnegative integer](hyp:n), [the reciprocal-maximum tolerance](goal) is the positive rational number $1/\max(n,1)$. -/
def inverseMaxTolerance (n : ℕ) : PosRat :=
  ⟨1 / (max n 1 : ℚ), by positivity⟩

/-- Coordinatewise rational interval refinement for matrices. -/
def MatrixSubinterval {ι κ : Type*} (I J : IntervalMatrix ι κ) : Prop :=
  ∀ i j, (I i j).Subinterval (J i j)

/-- For [a rational interval](hyp:I) and [a real number](hyp:x), [the containment relation](goal) holds precisely when [the real number is no smaller than the interval's lower endpoint](step:1) and [no larger than its upper endpoint](step:2), after the rational endpoints are viewed as real numbers. -/
def Contains (I : RatInterval) (x : ℝ) : Prop :=
  (I.lo : ℝ) ≤ x ∧ x ≤ (I.hi : ℝ)

/-- For [two rational intervals](hyp:I,J), [the subinterval relation](goal) holds precisely when [the second interval's lower endpoint is no greater than the first interval's lower endpoint](step:1) and [the first interval's upper endpoint is no greater than the second interval's upper endpoint](step:2). -/
def Subinterval (I J : RatInterval) : Prop :=
  J.lo ≤ I.lo ∧ I.hi ≤ J.hi

/-- For [two rational intervals](hyp:I,J), [their interval sum](goal) has [lower endpoint equal to the sum of the lower endpoints](step:1), upper endpoint equal to the sum of the upper endpoints, and valid endpoint order. -/
def add (I J : RatInterval) : RatInterval :=
  ⟨I.lo + J.lo, I.hi + J.hi, add_le_add I.lo_le_hi J.lo_le_hi⟩

/-- For [a rational interval](hyp:I), [a rational widening amount](hyp:e) [that is nonnegative](hyp:he), [the expanded interval](goal) has [lower endpoint equal to the original lower endpoint minus the widening amount](step:1), upper endpoint equal to the original upper endpoint plus the widening amount, and valid endpoint order. -/
def expand (I : RatInterval) (e : ℚ) (he : 0 ≤ e) : RatInterval :=
  ⟨I.lo - e, I.hi + e, by linarith [I.lo_le_hi]⟩

/-- For [a rational interval](hyp:I), [its interval negation](goal) has [lower endpoint equal to the negative of the original upper endpoint](step:1), upper endpoint equal to the negative of the original lower endpoint, and valid endpoint order. -/
def neg (I : RatInterval) : RatInterval :=
  ⟨-I.hi, -I.lo, neg_le_neg I.lo_le_hi⟩

/-- For [a rational interval](hyp:I) and [a precision index](hyp:n), [the exponential interval evaluation](goal) has [lower endpoint equal to the lower endpoint of the scalar exponential enclosure at the input interval's lower endpoint](step:1), upper endpoint equal to the upper endpoint of the scalar exponential enclosure at the input interval's upper endpoint, and valid endpoint order. -/
def expInterval (I : RatInterval) (n : ℕ) : RatInterval :=
  ⟨expIntervalLo I n, expIntervalHi I n, expInterval_wellFormed I n⟩

/-- Exponential interval evaluation uses monotonicity and scalar endpoint enclosures. -/
def expIntervalLo (I : RatInterval) (n : ℕ) : ℚ :=
  (expScalar I.lo n).lo

/-- For [a rational number](hyp:q) and [a nonnegative polynomial degree](hyp:n), [the exponential Taylor partial sum](goal) is the sum of the terms $q^k/k!$ for every integer $k$ from zero through $n$. -/
def expPartial (q : ℚ) (n : ℕ) : ℚ :=
  ∑ k ∈ Finset.range (n + 1), q ^ k / (k.factorial : ℚ)

/-- For [a rational exponential argument](hyp:q) and [a strictly positive rational target width](hyp:ε), [the exponential precision index](goal) is the product of one plus the target-width denominator and two copies of one plus the exponential scaling factor. -/
def expPrecision (q : ℚ) (ε : PosRat) : ℕ :=
  (ε.1.den + 1) * (expScale q + 1) * (expScale q + 1)

/-- For [a rational exponential argument](hyp:q) and [a nonnegative polynomial degree](hyp:n), [the raw exponential enclosure](goal) is the natural-power interval obtained by raising the reduced exponential enclosure to the exponential scaling factor. -/
def expRaw (q : ℚ) (n : ℕ) : RatInterval :=
  (expReducedRaw (expReduced q) n).npow (expScale q)

/-- For [a rational number](hyp:q) and [a strictly positive rational target width](hyp:ε), [the logarithm precision index](goal) is the product of one plus the target-width denominator and two copies of one plus the sum of the absolute numerator and denominator of the rational number. -/
def logPrecision (q : ℚ) (ε : PosRat) : ℕ :=
  (ε.1.den + 1) * (q.num.natAbs + q.den + 1) * (q.num.natAbs + q.den + 1)

/-- For [a base rational interval and an exponent rational interval](hyp:base,exponent) [whose base interval has a strictly positive lower endpoint](hyp:hbase), and [a precision index](hyp:n), [the raw real-power interval](goal) is the exponential interval of the product of the exponent interval and the logarithm interval of the base. -/
def rpowRaw (base exponent : RatInterval) (hbase : 0 < base.lo) (n : ℕ) : RatInterval :=
  expInterval (RatInterval.mul exponent (logInterval base hbase n)) n

/-- Coordinatewise rational interval refinement for vectors. -/
def VectorSubinterval {ι : Type*} (I J : IntervalVector ι) : Prop :=
  ∀ i, (I i).Subinterval (J i)

/-- The finite interval sum is the ordinary finite sum using outward interval addition. -/
def intervalSum {ι : Type*} [Fintype ι] (I : ι → RatInterval) : RatInterval :=
  ∑ i, I i

/-- [A finite dimension](hyp:d) determines [the normalized cube](goal), whose coordinates all lie
between minus one and one.
-/
def normalizedCube (d : ℕ) : Set (Fin d → ℝ) :=
  {x | ∀ i, x i ∈ Set.Icc (-1 : ℝ) 1}

/-- [A finite dimension](hyp:d) determines [the standard period box](goal), whose coordinates all
lie between minus π and π.
-/
def periodBox (d : ℕ) : Set (Fin d → ℝ) :=
  {x | ∀ i, x i ∈ Set.Icc (-Real.pi) Real.pi}

/-- The bad region of a cell contains points at distance at least `δ` from
one of that cell's reproduction points. -/
def badRegion (S k : ℕ) (δ : ℝ) (B : Fin k → Set ℝ)
    (z : Fin k → Fin S → ℝ) (j : Fin k) : Set ℝ :=
  B j ∩ {x | ∃ s : Fin S, δ ≤ |x - z j s|}

