/-- Given [a real matrix with two rows](hyp:H), [its left Gram matrix](goal) records all pairwise inner products of those rows. -/
def leftGram (H : Matrix (Fin 2) E ℝ) : Matrix (Fin 2) (Fin 2) ℝ :=
  H * H.transpose

/-- Given [a square matrix dimension](hyp:p) and [two real endpoints](hyp:c,C), the [Loewner interval](goal) is the set of real square matrices for which (1) [the matrix minus the lower endpoint times the identity is positive semidefinite](step:1), and (2) the upper endpoint times the identity minus the matrix is positive semidefinite. -/
def loewnerSet (p : ℕ) (c C : ℝ) : Set (Matrix (Fin p) (Fin p) ℝ) :=
  {G | (G - c • (1 : Matrix (Fin p) (Fin p) ℝ)).PosSemidef ∧
    (C • (1 : Matrix (Fin p) (Fin p) ℝ) - G).PosSemidef}

/-- Given [a real two-vector](hyp:v), [its outer-product matrix](goal) has entries $v_i v_j$; it has rank at most one (exactly one for a nonzero vector) and is the orthogonal projector onto the vector's direction when the vector has unit length. -/
def outerProjector (v : Fin 2 → ℝ) : Matrix (Fin 2) (Fin 2) ℝ :=
  fun i j => v i * v j

/-- Given [a real two-by-two matrix](hyp:G), [the symmetric-matrix discriminant](goal) is the squared diagonal difference plus four times the squared upper off-diagonal entry. The lower off-diagonal entry is ignored, so this is the discriminant of the characteristic polynomial only for a symmetric matrix. -/
def rootDiscriminant (G : Matrix (Fin 2) (Fin 2) ℝ) : ℝ :=
  (G 0 0 - G 1 1) ^ 2 + 4 * (G 0 1) ^ 2

/-- [The strict-gap region](goal) consists of real two-by-two matrices whose lower quadratic-formula root is strictly below their upper root. -/
def strictGapSet : Set (Matrix (Fin 2) (Fin 2) ℝ) :=
  {G | lambda₂ G < lambda₁ G}

/-- For a [coordinate index set](hyp:ι), [a real-valued center vector](hyp:x0), and [a real
radius](hyp:r), the [closed sup-norm ball](goal) is the set of real-valued vectors whose every
coordinate differs from the corresponding coordinate of the center by at most that radius. -/
def supBall {ι : Type*} (x0 : ι → ℝ) (r : ℝ) : Set (ι → ℝ) :=
  {x | ∀ i, |x i - x0 i| ≤ r}

/-- [The regularity region](goal) contains [rank-one Wald inputs](hyp:E) whose left Gram matrix has distinct roots and a strictly positive upper root. -/
def waldRegularSet : Set (WaldInput E) :=
  {x | leftGram x.1 ∈ strictGapSet ∧ 0 < lambda₁ (leftGram x.1)}

/-- For [a real value](hyp:c), [the constant slice function](goal) is [the function taking that value at every slice point](step:1). -/
def constFn (c : ℝ) : SliceFn n M :=
  WithLp.toLp 2 (fun _ => c)

/-- For [a population size](hyp:n), [a slice size](hyp:M), and [a degree bound](hyp:d),
[the degree-at-most subspace](goal) is [the linear span of inclusion monomials indexed by sets no larger than that bound](step:1). -/
def degreeAtMost (n M d : ℕ) : Submodule ℝ (SliceFn n M) :=
  Submodule.span ℝ {f | ∃ S : Finset (Fin n), S.card ≤ d ∧ f = inclusionMonomial (M := M) S}

/-- For [a set of labelled units](hyp:S), [its disjointness indicator](goal) is [one at slice points disjoint from that set and zero elsewhere](step:1). -/
def disjointIndicator (S : Finset (Fin n)) : SliceFn n M :=
  WithLp.toLp 2 (fun A => if Disjoint S A.1 then 1 else 0)

/-- For [a set of labelled units](hyp:S), [its inclusion monomial](goal) is [one on slice points containing that set and zero elsewhere](step:1). -/
def inclusionMonomial (S : Finset (Fin n)) : SliceFn n M :=
  WithLp.toLp 2 (fun A => if S ⊆ A.1 then 1 else 0)

