  Manifold.IsSmoothEmbedding I (modelWithCornersSelf ℝ E) 2 f →
    ∀ (φ ψ : OpenPartialHomeomorph M H),
      φ ∈ IsManifold.maximalAtlas I 2 M →
        ψ ∈ IsManifold.maximalAtlas I 2 M →
          ∀ x ∈ φ.source,
            x ∈ ψ.source →
              ∀ (v w : F),
                have q := ↑(φ.extend I) ∘ ↑(ψ.extend I).symm;
                have s := (ψ.extend I).target;
                have y := ↑(ψ.extend I) x;
                have D := fderivWithin ℝ q s y;
                have Hq := fderivWithin ℝ (fun z => fderivWithin ℝ q s z) s y;
                ((Causalean.Mathlib.Geometry.Manifold.EmbeddedNormalGeometry.chartHessian I f ψ x) v) w = ((Causalean.Mathlib.Geometry.Manifold.EmbeddedNormalGeometry.chartHessian I f φ x) (D v)) (D w) + (Causalean.Mathlib.Geometry.Manifold.EmbeddedNormalGeometry.chartDifferential I f φ x) ((Hq v) w)

