/-- The closed unit normal disk bundle of a family of subspaces over a base consists of the
pairs of a base point and an ambient vector orthogonal to the subspace at that point with norm at
most one. -/
def normalDiskSet (T : X → Submodule ℝ E) : Set (X × E) :=
  {z | z.2 ∈ (T z.1)ᗮ ∧ ‖z.2‖ ≤ 1}

/-- Given [a finite word](hyp:u) and [a final symbol](hyp:x), [append the symbol to the word](goal). -/
def appendSymbol {k : Nat} (u : Fin k → Ω) (x : Ω) : Fin (k + 1) → Ω :=
  Fin.lastCases x u

/-- The Euclidean vector obtained from [a finite real vector](hyp:x) by [taking the absolute value of every coordinate](goal) [is given coordinate by coordinate](step:1). -/
def absVec (x : EVec ι) : EVec ι :=
  WithLp.toLp 2 fun i => |x i|

/-- The greatest quadratic Rayleigh-form value among [the coordinate vectors whose squared coordinates sum to one for a finite real matrix](hyp:A), called [the coordinate-sphere top Rayleigh value](goal), [is given by a supremum](step:1). For an empty coordinate type no such vector exists and the supremum of the empty set is zero by convention. -/
def coordinateSphereRayleighValue (A : Matrix ι ι ℝ) : ℝ :=
  sSup {r : ℝ | ∃ x : ι → ℝ, (∑ i, x i ^ 2) = 1 ∧
    r = ∑ i, x i * (A.mulVec x) i}

/-- The quadratic form associated with [a finite real matrix](hyp:A) and [a Euclidean coordinate vector](hyp:x), called [its Rayleigh form](goal), [is given by the vector-matrix-vector quadratic sum](step:1). -/
def rayleighForm (A : Matrix ι ι ℝ) (x : EVec ι) : ℝ :=
  ∑ i, x i * (A.mulVec x) i

/-- The principal submatrix of [a real square matrix](hyp:A) on [a finite set of coordinates](hyp:s), called [its restricted matrix](goal), [is given by selecting those rows and columns](step:1). -/
def restrictMatrix (A : Matrix ι ι ℝ) (s : Finset ι) : Matrix s s ℝ :=
  A.submatrix Subtype.val Subtype.val

/-- The Euclidean vector obtained by restricting [a finite real vector](hyp:x) to [a finite coordinate set](hyp:s), called [its restricted vector](goal), [is given by retaining those coordinates](step:1). -/
def restrictVec (s : Finset ι) (x : EVec ι) : EVec s :=
  WithLp.toLp 2 fun i => x i.1

/-- The greatest quadratic Rayleigh-form value among [the Euclidean unit vectors for a finite real matrix](hyp:A), called [the Euclidean-sphere top Rayleigh value](goal), [is given by a supremum](step:1). For an empty coordinate type there are no unit vectors and the supremum of the empty set is zero by convention. -/
def sphereRayleighValue (A : Matrix ι ι ℝ) : ℝ :=
  sSup {r : ℝ | ∃ x : EVec ι, ‖x‖ = 1 ∧ r = rayleighForm A x}

/-- The Euclidean vector obtained by extending [a vector on a finite coordinate subtype](hyp:x) by zero outside [that finite coordinate set](hyp:s), called [its zero extension](goal), [is given coordinate by coordinate](step:1). -/
def zeroExtendVec (s : Finset ι) (x : EVec s) : EVec ι :=
  WithLp.toLp 2 fun i => if hi : i ∈ s then x ⟨i, hi⟩ else 0

/-- A real scalar family, over an arbitrary index type, has pairwise gap at least `gap`. With [its explicit inputs](hyp:values,gap), [the defined object](goal) is [given by the displayed formula](step:1). -/
def PairwiseGap {ι : Type*} (values : ι → ℝ) (gap : ℝ) : Prop :=
  ∀ i j, i ≠ j → gap ≤ |values i - values j|

/-- The probe family containing `q-1` copies of `u` followed by one copy of `w`, for positive `q`;
for `q = 0` it is the empty family. With [its explicit inputs](hyp:u,w), [the defined object](goal) is [given by the displayed formula](step:1). -/
def pencilProbes {p q : ℕ} (u w : Vec p) : Fin q → Vec p :=
  fun a => if a.1 + 1 = q then w else u

/-- The order-`r` rank-one tensor power of a vector. With [its explicit inputs](hyp:r,c), [the defined object](goal) is [given by the displayed formula](step:1). -/
def rankOneTensor (r : ℕ) {p : ℕ} (c : Vec p) : Tensor p r :=
  fun I => ∏ k, c (I k)

/-- Given [real numbers \(a\), \(b\), and \(s\)](hyp:a,b,s), the [moment slice](goal) is the set
of probability measures on the real line that [are supported on the closed interval from \(a\) to
\(b\)](step:1,step:2), have mean zero, and have second moment \(s\). -/
def MomentSlice (a b s : ℝ) : Set (Measure ℝ) :=
  {μ | IsProbabilityMeasure μ ∧ μ (Set.Icc a b)ᶜ = 0 ∧
        (∫ x, x ∂μ = 0) ∧ (∫ x, x ^ 2 ∂μ = s)}

/-- Given [an affine constraint system](hyp:Γ), its [feasible slack set](goal) is given by
[the slacks for which some coordinate vector is common-slack feasible](step:1).

The set of feasible common-slack values. -/
def commonSlackSet {n : ℕ} (Γ : AffineSystem n) : Set ℝ :=
  {δ | ∃ x, commonSlackFeasible Γ x δ}

/-- Given [a finite list of checked polynomial constraints](hyp:Γ), its [direct weak polynomial
cell](goal) is given by [weak satisfaction of every polynomial constraint](step:1).

The weak cell written directly in polynomial syntax. -/
def polynomialWeakCell {n : ℕ} (Γ : List (PolynomialConstraint n)) : Set (Fin n → ℝ) :=
  {x | ∀ c ∈ Γ, MvPolynomial.eval x c.polynomial ≤ 0}

/-- Given [an affine constraint system](hyp:Γ), its [strict cell](goal) is given by [the
points satisfying every listed constraint using its original comparison](step:1).

The strict cell of a finite mixed affine system. -/
def strictCell {n : ℕ} (Γ : AffineSystem n) : Set (Fin n → ℝ) :=
  {x | ∀ c ∈ Γ, c.strictHolds x}

/-- Given [an affine constraint system](hyp:Γ), its [weak relaxation](goal) is given by [the
points weakly satisfying every listed constraint](step:1).

The weak relaxation of a finite mixed affine system. -/
def weakCell {n : ℕ} (Γ : AffineSystem n) : Set (Fin n → ℝ) :=
  {x | ∀ c ∈ Γ, c.weakHolds x}

/-- A [fixed compact polytope](hyp:P) has a [feasible weight set](goal) consisting of its
nonnegative vectors that satisfy every defining linear equality. -/
def Polytope.weights (P : Polytope ι κ) : Set (EuclideanSpace ℝ ι) :=
  {α | (∀ i, 0 ≤ α i) ∧ ∀ j, (∑ i, P.A j i * α i) = P.b j}

/-- A [fixed polytope](hyp:P), [quadratic family](hyp:Q), and [parameter](hyp:θ) determine
the [real max-min value](goal), the supremum of all attained weighted-quadratic minima. -/
def value (P : Polytope ι κ) (Q : Quadratics Θ ι) (θ : Θ) : ℝ :=
  sSup {j : ℝ | ∃ α ∈ P.weights, ∃ t : ℝ,
    Q.objective θ α t = j ∧
    ∀ u : ℝ, Q.objective θ α t ≤ Q.objective θ α u}

/-- The signed central evaluator uses CDF symmetry when the endpoint is
negative. -/
def centralInterval (q : ℚ) (c : CentralCertificate) : RatInterval :=
  if 0 ≤ q then centralMagnitudeInterval |q| c
  else reflectInterval (centralMagnitudeInterval |q| c)

/-- The exact interval computed from the caller's split and Taylor degree. -/
def expCertificateInterval {q : ℚ} (c : ExpCertificate q) : RatInterval :=
  (expTaylorInterval (q / (c.split : ℚ)) c.degree).npow c.split

/-- The exact rational Gaussian-integral partial sum through degree index `n`. -/
def gaussianIntegralPartial (x : ℚ) (n : ℕ) : ℚ :=
  ∑ k ∈ Finset.range (n + 1), gaussianIntegralTerm x k

/-- Reflecting an interval `I` across one half produces the interval `1 - I`. -/
def reflectInterval (I : RatInterval) : RatInterval :=
  (RatInterval.point 1).sub I

/-- The certified rational interval for the density `φ(|q|)`. -/
def tailDensityInterval (q : ℚ) (c : TailCertificate q) : RatInterval :=
  c.normalization.enclosure.mul c.exponential.enclosure

/-- The signed tail evaluator returns the upper-tail interval directly for a
negative endpoint and reflects it for a nonnegative endpoint. -/
def tailInterval (q : ℚ) (c : TailCertificate q) : RatInterval :=
  let upperTail := millsTailInterval |q| (tailDensityInterval q c)
  if 0 ≤ q then reflectInterval upperTail else upperTail

/-- The finite `ℓ¹` distance is the sum of absolute coordinate differences. -/
def l1Distance {ι : Type*} [Fintype ι] (p q : ι → ℝ) : ℝ :=
  ∑ i, |p i - q i|

/-- Given [a measurable classifier partition](hyp:p) and [a cell index](hyp:j), the
[cell set](goal) consists of the observations assigned to that index. -/
def cellSet (p : FiniteMeasurablePartition X ι) (j : ι) : Set X :=
  p.cell ⁻¹' {j}

/-- For [a fixed array](hyp:x) and [a requested length](hyp:m), the [capped prefix](goal) is the
genuine prefix in the right summand when the request fits
and the distinguished left summand on
overflow, so overflow is never confused with an empty observation. -/
def cappedPrefix {n : ℕ} (x : Fin n → X) (m : ℕ) : Unit ⊕ FiniteSample X :=
  if h : m ≤ n then Sum.inr (prefixOfLE x m h) else Sum.inl ()

/-- For [a prescribed count profile](hyp:c), the [count fibre](goal) is the event that every
component sample has its specified count. -/
def countFiber {Y : Type*} [MeasurableSpace Y] (c : ι → ℕ) :
    Set (ι → FiniteSample Y) :=
  {q | ∀ j, (q j).count = c j}

/-- The first random coordinate of a canonical three-block sample. -/
def firstThreeCoord {A : Type uA} {B : Type uB} {C : Type uC} :
    ThreeBlock A B C → A := fun q ↦ q.1

/-- The second random coordinate of a canonical three-block sample. -/
def secondThreeCoord {A : Type uA} {B : Type uB} {C : Type uC} :
    ThreeBlock A B C → B := fun q ↦ q.2.1

/-- The conditioning coordinate of a canonical three-block sample. -/
def thirdThreeCoord {A : Type uA} {B : Type uB} {C : Type uC} :
    ThreeBlock A B C → C := fun q ↦ q.2.2

/-- The third coordinate of a four-block sample is its `V` block. -/
def vCoord {X : Type uX} {Y : Type uY} {V : Type uV} {Z : Type uZ} :
    FourBlock X Y V Z → V := fun q => q.2.2.1

/-- The first coordinate of a four-block sample is its `X` block. -/
def xCoord {X : Type uX} {Y : Type uY} {V : Type uV} {Z : Type uZ} :
    FourBlock X Y V Z → X := fun q => q.1

/-- The second coordinate of a four-block sample is its `Y` block. -/
def yCoord {X : Type uX} {Y : Type uY} {V : Type uV} {Z : Type uZ} :
    FourBlock X Y V Z → Y := fun q => q.2.1

/-- A four-block sample determines the combined block `(Y,V)`. -/
def yvCoord {X : Type uX} {Y : Type uY} {V : Type uV} {Z : Type uZ} :
    FourBlock X Y V Z → Y × V := fun q => (q.2.1, q.2.2.1)

/-- The fourth coordinate of a four-block sample is its `Z` block. -/
def zCoord {X : Type uX} {Y : Type uY} {V : Type uV} {Z : Type uZ} :
    FourBlock X Y V Z → Z := fun q => q.2.2.2

/-- A four-block sample determines the conditioning pair `(Z,V)`. -/
def zvCoord {X : Type uX} {Y : Type uY} {V : Type uV} {Z : Type uZ} :
    FourBlock X Y V Z → Z × V := fun q => (q.2.2.2, q.2.2.1)

/-- A four-block sample determines the conditioning pair `(Z,Y)`. -/
def zyCoord {X : Type uX} {Y : Type uY} {V : Type uV} {Z : Type uZ} :
    FourBlock X Y V Z → Z × Y := fun q => (q.2.2.2, q.2.1)

/-- A [real sequence](hyp:f) at [an index](hyp:n) has [a forward add-one increment](goal), given by [the next value minus the current value](step:1). -/
def addOne (f : Nat → Real) (n : Nat) : Real :=
  f (n + 1) - f n

/-- A [nonnegative Poisson rate](hyp:lambda) and [count value](hyp:n) determine [the real Poisson probability mass at that count](goal), given by [the standard exponential--factorial mass formula](step:1). -/
def poissonWeight (lambda : NNReal) (n : Nat) : Real :=
  Real.exp (-(lambda : Real)) * (lambda : Real) ^ n / Nat.factorial n

/-- A [cutoff index](hyp:K) and [real sequence](hyp:f) determine [its support truncation](goal), given by [retaining exactly the values below the cutoff and setting all later values to zero](step:1). -/
def supportTruncation (K : Nat) (f : Nat → Real) : Nat → Real :=
  fun n ↦ if n < K then f n else 0

/-- Given [two binary cube vertices](hyp:u,v), [face adjacency](goal) is [the condition that exactly one coordinate differs](step:1). -/
def FaceAdjacentVertex {d : ℕ} (u v : Fin d → Bool) : Prop :=
  ∃ i : Fin d, u i ≠ v i ∧ ∀ j : Fin d, j ≠ i → u j = v j

/-- Given [a real cube point](hyp:x), [unit-cube membership](goal) is [the condition that every coordinate lies between zero and one](step:1). -/
def InUnitCube {d : ℕ} (x : Fin d → ℝ) : Prop :=
  ∀ i, x i ∈ Set.Icc (0 : ℝ) 1

/-- Given [a parent grid cell and binary child vertex](hyp:u,b), [the child-grid coordinate](goal) is [twice the parent coordinate plus the child bit](step:1). -/
def childGridCoord {d : ℕ} (u : Fin d → ℕ) (b : Fin d → Bool) : Fin d → ℕ :=
  fun i => 2 * u i + if b i then 1 else 0

/-- [The reflected Gray code](goal) of [a natural-number index k](hyp:k) is [the bitwise
exclusive-or of k with k shifted right by one bit](step:1). -/
def reflectedGray (k : ℕ) : ℕ := Nat.xor k (k / 2)

/-- Given [two real cube points](hyp:x,y), [their squared Euclidean distance](goal) is [the sum of squared coordinate differences](step:1). -/
def sqEuclideanDist {d : ℕ} (x y : Fin d → ℝ) : ℝ :=
  ∑ i, (x i - y i) ^ 2

/-- [Adjacent thresholds](goal) are the positive positions in [a finite ordered instrument
support](hyp:K), each marking the boundary between consecutive support points. -/
abbrev Adj (K : ℕ) := {j : Fin K // 0 < j.val}

/-- [A margin-crossing subgroup](goal) contains units in [a variable-intensity IV
system](hyp:S) whose potential dose crosses [the selected treatment margin](hyp:j) when the
instrument moves between [the two selected values](hyp:z0,z1). -/
def crossingEvent (z0 z1 : 𝒵) (j : Fin J) : Set P.Ω :=
  {ω | OrderedTreatment.Crossing (S.DofZ z0 ω) (S.DofZ z1 ω) j}

/-- Given [a binary-treatment backdoor system](hyp:S), [a treatment arm](hyp:d), and [a sensitivity level](hyp:Λ), the [calibrated MSM ambiguity set](goal) contains exactly the candidate complete-propensity functions that [belong to the MSM ambiguity set at that level](step:1) and satisfy the calibration condition.

**The calibrated MSM ambiguity set:** odds-ratio-box members that also satisfy
calibration. -/
def MSMSetCalib (d : Bool) (Λ : ℝ) : Set (P.Ω → ℝ) :=
  { etilde | etilde ∈ S.MSMSet d Λ ∧ S.Calibrated d etilde }

/-- Given [a binary-treatment backdoor system](hyp:S) and [a sensitivity level](hyp:Λ), the
[observed calibrated treated candidate set](goal) consists of candidates that belong to the
calibrated marginal-sensitivity set and are observed-data measurable on the treated
arm. -/
def MSMSetCalibObs (Λ : ℝ) : Set (P.Ω → ℝ) :=
  { etilde | etilde ∈ S.MSMSetCalib true Λ ∧ S.ObservedOnTreated etilde }

/-- Given [a binary-treatment backdoor system](hyp:S) and [a sensitivity level](hyp:Λ), the
[observed calibrated control candidate set](goal) consists of candidates that belong to the
calibrated control marginal-sensitivity set and are observed-data measurable on the
control arm. -/
def MSMSetCalibObs0 (Λ : ℝ) : Set (P.Ω → ℝ) :=
  { etilde | etilde ∈ S.MSMSetCalib false Λ ∧ S.ObservedOnControl etilde }

/-- Given [an observed backdoor system](hyp:S) and [a sensitivity level](hyp:Λ), the
[compatible treated means](goal) are the means of `Y(1)` across all compatible full-data
models in the ambient universe. -/
def compatibleTargets (Λ : ℝ) : Set ℝ :=
  {θ | ∃ M : MSMDataCompatible.{u, u} S Λ, M.target = θ}

/-- For [a binary instrument value](hyp:z) and [a canonical sample-space point](hyp:ω), the [latent treatment response](goal) is that point's treatment response under the specified instrument value. -/
def dArmω (z : Bool) (ω : SOmega) : Bool :=
  if z then ω.2.2.1 else ω.2.1

/-- For [a binary treatment value](hyp:d) and [a canonical sample-space point](hyp:ω), the [latent outcome response](goal) is that point's outcome response under the specified treatment value. -/
def yArmω (d : Bool) (ω : SOmega) : Bool :=
  if d then ω.2.2.2.2 else ω.2.2.2.1

entries.doc:
For a [potential-outcome system](hyp:P) and [its Balke--Pearl observational system](hyp:S), the [first auxiliary free mass for
the third lower-bound witness](goal) is $\max\{0,p_{011\mid0}-p_{010\mid0}-p_{100\mid0}
+p_{101\mid0}\}$, where $p_{yd\mid z}$ is the observed outcome--treatment cell probability.

For a [potential-outcome system](hyp:P) and [its Balke--Pearl observational system](hyp:S), the [first auxiliary free mass for
the fourth lower-bound witness](goal) is $\max\{0,p_{010\mid0}-p_{011\mid0}+p_{100\mid0}
-p_{101\mid0}\}$, where $p_{yd\mid z}$ is the observed outcome--treatment cell probability.

For a [potential-outcome system](hyp:P) and [its Balke--Pearl observational system](hyp:S), the [first auxiliary free mass for
the third upper-bound witness](goal) is $\max\{0,p_{010\mid0}-p_{011\mid0}+p_{100\mid0}
-p_{101\mid0}\}$, where $p_{yd\mid z}$ is the observed outcome--treatment cell probability.

For a [potential-outcome system](hyp:P) and [its Balke--Pearl observational system](hyp:S), the [second auxiliary free mass for
the third upper-bound witness](goal) is $\max\{0,1-p_{000\mid0}-p_{001\mid0}-p_{010\mid0}
-p_{100\mid0}\}$, where $p_{yd\mid z}$ is the observed outcome--treatment cell probability.

For a [potential-outcome system](hyp:P) and [its Balke--Pearl observational system](hyp:S), the [first auxiliary free mass for
the fourth upper-bound witness](goal) is $\max\{0,-p_{010\mid0}+p_{011\mid0}-p_{100\mid0}
+p_{101\mid0}\}$, where $p_{yd\mid z}$ is the observed outcome--treatment cell probability.

For a [potential-outcome system](hyp:P) and [its Balke--Pearl observational system](hyp:S), the [second auxiliary free mass for
the fourth upper-bound witness](goal) is $\max\{0,1-p_{000\mid0}-p_{001\mid0}-p_{011\mid0}
-p_{101\mid0}\}$, where $p_{yd\mid z}$ is the observed outcome--treatment cell probability.

For [a potential-outcomes system](hyp:P), [a binary Balke--Pearl system on it](hyp:S), [an instrument value](hyp:z), and [a treatment value](hyp:d), the [joint intervention regime](goal) sets the instrument to the specified instrument value and the treatment to the specified treatment value.

Built as a disjoint union of the singleton regimes `{Z ← z}` and `{D ← d}`;
disjointness uses `S.hZD : Z ≠ D`.

The [baseline potential outcome](goal) in [a two-period DID system](hyp:S)
[records what each unit's pre-period outcome would be under the selected arm](step:1);
[the arm](hyp:d) is useful for stating and testing no anticipation.

entries.source:
/-- [The interval-complier population](goal) for [a Heckman--Roy model](hyp:S)
[is indexed by two instrument values](hyp:z₀,z₁) and [consists of units whose latent rank
lies above the first threshold and at or below the second](step:1). -/
def intervalComplierEvent (z₀ z₁ : α) : Set P.Ω :=
  { ω | S.p z₀ < S.factualU ω ∧ S.factualU ω ≤ S.p z₁ }

/-- [The complier population](goal) in [a binary IV system](hyp:S) consists of units induced
into treatment by switching the instrument on and not treated when it is off. -/
def complierEvent : Set P.Ω :=
  { ω | S.DofZ true ω = true ∧ S.DofZ false ω = false }

entries.doc:
[The treatment-specific potential outcome](goal) is the response each unit would have
if [the proximal system](hyp:S) intervened to set treatment to [the chosen arm](hyp:a),
[using the counterfactual outcome under that intervention](step:1).

entries.source:
/-- For [a potential-outcome system](hyp:P), [a measurable analysis scale](hyp:α), [a potential-outcome variable](hyp:a), and [a value on that scale](hyp:x), [the factual-value event](goal) is the set of all sample-space units whose factual value of the variable equals that value.

The event `{factual a = x}` as a measurable set. -/
def event (a : POVar P α) (x : α) : Set P.Ω := a.factual ⁻¹' {x}

/-- [For a panel with a finite horizon of $T$ periods](hyp:T) and [a finite adoption period $g$](hyp:g), [the finite adoption path](goal) is the path whose adoption date is $g$, rather than the never-treated date. -/
def finite {T : ℕ} (g : Fin T) : WithTop (Fin T) :=
  (g : WithTop (Fin T))

/-- [For a finite-period horizon](hyp:T) and [an adoption path $h$](hyp:h), [the eventually-treated predicate](goal) holds exactly when $h$ has a finite adoption date. -/
def isEventuallyTreated {T : ℕ} (h : WithTop (Fin T)) : Prop :=
  isFinite h

/-- [For a finite-period horizon](hyp:T) and [an adoption path $a$](hyp:a), [the finite-path predicate](goal) holds exactly when its adoption date is not the never-treated date. -/
def isFinite {T : ℕ} (a : WithTop (Fin T)) : Prop :=
  a ≠ ⊤

/-- [For a finite-period horizon](hyp:T) and [an adoption path $a$](hyp:a), [the infinite-path predicate](goal) holds exactly when its adoption date is the never-treated date. -/
def isInfinite {T : ℕ} (a : WithTop (Fin T)) : Prop :=
  a = ⊤

/-- [For a finite-period horizon](hyp:T) and [an adoption path $h$](hyp:h), [the never-treated predicate](goal) holds exactly when $h$ has the never-treated adoption date. -/
def isNeverTreated {T : ℕ} (h : WithTop (Fin T)) : Prop :=
  isInfinite h

/-- [For a finite-period horizon](hyp:T), [an adoption path $a$](hyp:a), and [a period $t$ in that horizon](hyp:t), [the treated-by-$t$ predicate](goal) holds exactly when the adoption date is no later than $t$. -/
def le {T : ℕ} (a : WithTop (Fin T)) (t : Fin T) : Prop :=
  a ≤ (t : WithTop (Fin T))

/-- [For a finite-period horizon](hyp:T), [an adoption path $a$](hyp:a), and [a period $t$ in that horizon](hyp:t), [the untreated-at-$t$ predicate](goal) holds exactly when $t$ is strictly before the adoption date. -/
def lt {T : ℕ} (a : WithTop (Fin T)) (t : Fin T) : Prop :=
  (t : WithTop (Fin T)) < a

/-- [For an event-study population $E$](hyp:E) and [an adoption path $h$](hyp:h),
[the adoption-path cell](goal) is the event consisting exactly of units whose realized
adoption path is $h$. -/
def cell (E : EventStudyPopulation T) (h : WithTop (Fin T)) : Set E.Ω :=
  E.G ⁻¹' {h}

/-- For [an adoption-time path for the units over a finite number of periods](hyp:g), the [treated cells](goal) are precisely the unit-period pairs for which the unit's adoption time is no later than the period. -/
def TreatedCell : Type _ :=
  { c : I × Fin T // AdoptionPath.le (g c.1) c.2 }

/-- For [an adoption-time path for the units over a finite number of periods](hyp:g), the [untreated cells](goal) are precisely the unit-period pairs whose period is strictly before the unit's adoption time. They include every period of a never-treated unit and every pre-adoption period of a treated unit. -/
def UntreatedCell : Type _ :=
  { c : I × Fin T // AdoptionPath.lt (g c.1) c.2 }

/-- For [a set of real numbers](hyp:A) and [a real radius](hyp:r), the [Minkowski dilation](goal)
is the set of all sums $a+t$ such that $a$ belongs to the original set and $|t|\le r$.

This is the deterministic dilation on the right-hand side of Beresteanu–Molinari Theorem 2.4,
which identifies it with the union of their confidence collection when `A = Ȳₙ`. -/
def dilate (A : Set ℝ) (r : ℝ) : Set ℝ :=
  {x : ℝ | ∃ a ∈ A, ∃ t : ℝ, |t| ≤ r ∧ x = a + t}

