        let C₁ := Causalean.SCM.ID.containingCComponent (G.induce A) C;
        have hC₁ := fun x hv => hT (Causalean.SCM.ID.inducedAncestral_subset_left G T C (Causalean.SCM.ID.containingCComponent_induce_subset G A C hv));
