/-- A row and an outcome vector determine their finite iid product mass. -/
def mass (n : ℕ) (ys : Fin (M.N n) → Y) : ℝ :=
  ∏ i, M.w n (ys i)

/-- The product design of a row assigns each outcome vector its literal product mass. -/
def productDesign (n : ℕ) : FiniteDesign (Fin (M.N n) → Y) :=
  prodDesign (fun _ : Fin (M.N n) => M.coordinateDesign n)

/-- The unscaled score sum is the sum of all coordinate scores in a row. -/
def scoreSum (n : ℕ) (ys : Fin (M.N n) → Y) : ℝ :=
  ∑ i, M.f n (ys i)

/-- An ordered quadruple is constant when all four of its indices coincide. -/
def fourthConstant {k : ℕ} (p : Fin 4 → Fin k) : Prop :=
  ∀ a, p a = p 0

/-- An ordered quadruple has a singleton coordinate when some index appears exactly once. -/
def fourthHasSingleton {k : ℕ} (p : Fin 4 → Fin k) : Prop :=
  ∃ i : Fin k, (Finset.univ.filter (fun a : Fin 4 => p a = i)).card = 1

/-- Given [an index set of coefficients](hyp:K) and [a real bound](hyp:B), [the coefficient box](goal) is the set of real coefficient vectors indexed by that set for which every coordinate has absolute value at most $B$. -/
def CoeffBox (K : Type w) (B : ℝ) :=
  {θ : K → ℝ // ∀ k, |θ k| ≤ B}

/-- The [histogram failure event](goal) is the set of design and outcome vectors for which,
for some [design cell of the key map](hyp:key) and some [outcome bin of the family](hyp:bins),
the joint count differs from its conditional mean under the [outcome kernel](hyp:K) by
strictly more than √(2 · pMax · N_c · u) + u, where N_c is the number of design entries in
the cell and [pMax and u are the probability envelope and tail parameter](hyp:pMax,u). -/
def histogramBadEvent (key : D → C) (K : Kernel D Y) (bins : B → Set Y)
    (pMax u : ℝ) : Set ((Fin n → D) × (Fin n → Y)) :=
  {p | ∃ c b, bernsteinRadius (pMax * (cellCount key c p.1 : ℝ)) u <
    |(jointCount key (bins b) c p.1 p.2 : ℝ) - conditionalMean key K (bins b) c p.1|}

