/-- Given [a natural dimension](hyp:d), [the fixed-degree radial pseudo-dimension bound](goal) is the explicit Boolean-combination bound $2^{3(d+3)+1}$. -/
def fixedRadialPseudoDimBound (d : ℕ) : ℕ :=
  booleanCombinationVCBound 3 (d + 2)

/-- Given [an outer relative radius](hyp:b), [a maximal degree](hyp:p), and [a coefficient bound](hyp:B), [the radial-polynomial envelope](goal) is $(p+1)B$ times the radial-monomial envelope at that outer radius and degree. -/
def radialPolynomialEnvelope (b : ℝ) (p : ℕ) (B : ℝ) : ℝ :=
  ((p + 1 : ℕ) : ℝ) * B * radialMonomialEnvelope b p

/-- Given [a natural dimension](hyp:d) and [a maximal degree](hyp:p), [the radial pseudo-dimension bound](goal) is the explicit finite-union bound $2^{(p+1)(2^{3(d+3)+1}+1)+1}$ obtained by combining $p+1$ fixed-degree bounds. -/
def radialPseudoDimBound (d p : ℕ) : ℕ :=
  finiteUnionVCBound (p + 1) (fixedRadialPseudoDimBound d)

/-- Given [a Boolean classifier family](hyp:π) and [a natural number](hyp:d), [the property of having VC dimension at most that number](goal) means that, for every finite sample, the VC dimension of the label patterns realized on that sample is at most $d$. -/
def HasVCAtMost {κ : Type w} (π : κ → 𝒳 → Bool) (d : ℕ) : Prop :=
  ∀ (n : ℕ) (S : Fin n → 𝒳), (growthFamily π S).vcDim ≤ d

/-- Given [a multiplier and logarithmic level](hyp:H,L) and [a nonnegative Poisson mean](hyp:lambda),
the [self-normalized bad event](goal) contains counts whose absolute deviation exceeds one quarter
of the multiplier times their random radius. -/
def badEvent (H L : ℝ) (lambda : ℝ≥0) : Set ℕ :=
  {w | deviation lambda w > (H / 4) * radius L w}

/-- Given [a coordinate-cardinality cap](hyp:r) and [a moment order](hyp:t), the [finite-product
moment constant](goal) is a fixed power of ten depending only on those two quantities. -/
def productMomentConstant (r t : ℕ) : ℝ := 10 ^ (16 * (r + 1) * (t + 1))

/-- Given [a moment order](hyp:t), the [uniform scalar bad-event moment constant](goal) is a fixed
power of ten large enough for all orders through four. -/
def scalarBadMomentConstant (t : ℕ) : ℝ := 10 ^ (8 * t + 8)

/-- Given [a moment order](hyp:t), the [uniform unconditioned scalar moment constant](goal) is a
fixed power of ten large enough for all orders through four. -/
def scalarMomentConstant (t : ℕ) : ℝ := 10 ^ (4 * t + 4)

/-- For [a real-valued observation-weight function](hyp:q) and [a finite sample](hyp:omega), [the unnormalised local count](goal) is the sum of the weights assigned to all observations in the sample. -/
def localCount {N : ℕ} {X : Type*} (q : X → ℝ) (omega : Fin N → X) : ℝ :=
  ∑ i, q (omega i)

/-- Given [a real-valued family of functions on a covariate space](hyp:F), the [star hull of that family about zero](goal) is the set of all functions obtained by multiplying one member of the family by a real coefficient between zero and one, inclusive.

    Each element is an `α`-rescaling of some `F i` for `α ∈ [0, 1]`. -/
def starHull {ι 𝒳 : Type*} (F : ι → 𝒳 → ℝ) : Set (𝒳 → ℝ) :=
  {f | ∃ (i : ι) (α : ℝ), 0 ≤ α ∧ α ≤ 1 ∧ f = α • F i}

/-- For [an index set](hyp:ι), [an observation domain](hyp:𝒳), [a class of real-valued functions](hyp:F), [a real-valued functional on such functions](hyp:norm), and [a real radius](hyp:r), [the star-hull ball](goal) is the set of all star-hull functions whose functional value is at most the radius. -/
def starHullBall (F : ι → 𝒳 → ℝ) (norm : (𝒳 → ℝ) → ℝ) (r : ℝ) :
    Set (𝒳 → ℝ) :=
  starHull F ∩ {f | norm f ≤ r}

/-- For [a finite uniform-allocation experiment](hyp:E) and [a full-data point](hyp:z), the [sample statistic](goal) is the statistic computed from that point's allocation and observation. -/
def sampleStatistic (z : Allocation × Observation) : Statistic :=
  E.statistic z.1 z.2

