/-- Given [pool capacities](hyp:N), [the joint nonoverflow event](goal) is the event that
every requested prefix fits its coordinate pool. [It is given by the coordinatewise capacity
bounds](step:1). -/
def nonoverflowSet (N : I → ℕ) : Set (RandomizedPools X N) :=
  {z | ∀ i, (z i).2 ≤ N i}

/-- Given [pool capacities](hyp:N), [the overflow event](goal) is the event that at least one
requested prefix exceeds its coordinate pool. [It is given by the union of marginal overflow
events](step:1). -/
def overflowSet (N : I → ℕ) : Set (RandomizedPools X N) :=
  {z | ∃ i, N i < (z i).2}

/-- Given [the first requested prefix length](hyp:n) and [the second requested prefix
length](hyp:m), [the retention-failure event](goal) is that at least one raw record is too
short. [It is given by the union of the two lower-count events](step:1). -/
def retentionFailureSet (n m : ℕ) : Set (RawTwoPool X Y) :=
  {z | z.1.count < n} ∪ {z | z.2.count < m}

/-- Given [the first requested prefix length](hyp:n) and [the second requested prefix
length](hyp:m), [the retention-success event](goal) is that both raw records contain their
respective requested numbers of marks. [It is given by the conjunction of the two count
bounds](step:1). -/
def retentionSuccessSet (n m : ℕ) : Set (RawTwoPool X Y) :=
  {z | n ≤ z.1.count ∧ m ≤ z.2.count}

/-- Given [the first pool capacity](hyp:NX) and [the second pool capacity](hyp:NY), [the
joint nonoverflow event](goal) says that both requested prefixes fit in their respective
pools. [It is given by the conjunction of the two capacity bounds](step:1). -/
def nonoverflowSet (NX NY : ℕ) :
    Set (RandomizedPools (X := X) (Y := Y) NX NY) :=
  {z | z.1.2 ≤ NX ∧ z.2.2 ≤ NY}

/-- Given [the first pool capacity](hyp:NX) and [the second pool capacity](hyp:NY), [the
overflow event](goal) says that at least one requested prefix is too long. [It is given by the
union of the two marginal overflow events](step:1). -/
def overflowSet (NX NY : ℕ) :
    Set (RandomizedPools (X := X) (Y := Y) NX NY) :=
  {z | NX < z.1.2} ∪ {z | NY < z.2.2}

/-- For [a category-label function](hyp:group) and [a category](hyp:k), the [category event](goal) is the set of observations assigned that category. -/
def categoryEvent (group : Omega → kappa) (k : kappa) : Set Omega :=
  Causalean.Stat.groupEvent group k

/-- Given [an i.i.d. real sample](hyp:S), [a confidence level](hyp:α), and [a
sample size](hyp:n), the [simultaneous CDF-band coverage event](goal) consists of outcomes
for which the population CDF belongs to the empirical band at every real threshold. -/
def IIDSample.cdfBandCoverageEvent (S : IIDSample Ω ℝ μ P) (α : ℝ) (n : ℕ) : Set Ω :=
  {ω | ∀ x : ℝ, cdf P x ∈ S.cdfBand α n ω x}

/-- A [finite alphabet](hyp:C) has as its [coordinate probability simplex](goal) the subtype of
real vectors with nonnegative coordinates summing to one. -/
abbrev FinitePmf := {w : C → ℝ // w ∈ stdSimplex ℝ C}

/-- Given [a family of finite observation spaces indexed by design](hyp:X), [a lower action bound](hyp:l),
and [an upper action bound](hyp:u), [the feasible procedure-coordinate set](goal) contains exactly
those ambient coordinates whose design weights form a probability distribution and whose action
coordinates all lie in the closed interval from the lower to the upper bound. -/
def procedureSet (X : R → Type*) (l u : ℝ) : Set (Ambient R X) :=
  {z | z.1 ∈ stdSimplex ℝ R ∧ ∀ r x, z.2 r x ∈ Set.Icc l u}

/-- Three [monomial degrees](hyp:i,j,k) and [a parameter triple](hyp:t) of arrival mass p, propensity π, and conditional success probability μ determine [the mixed monomial](goal) as [the product pⁱ · (pπ)ʲ · (pπμ)ᵏ](step:1). -/
def mixedMonomial (i j k : ℕ) (t : MarkedParam) : ℝ :=
  t.1 ^ i * (t.1 * t.2.1) ^ j * (t.1 * t.2.1 * t.2.2) ^ k

/-- A [rescaling factor, scalar scale, and inverse coefficient](hyp:b,a,q) together with [a scalar atom](hyp:x) determine [the marked parameter triple](goal) by [sending the atom x = 0 to (0, 1/2, 1) and every other atom x to (b·x, (1 + q·a/x)/2, x/(x + q·a))](step:1). -/
noncomputable def scalarToTriple (b a q : ℝ) (x : ℝ) : MarkedParam :=
  if x = 0 then (0, 1 / 2, 1)
  else (b * x, (1 + q * a / x) / 2, x / (x + q * a))

/-- Valid cell data have scores bounded by one and selection contained in the active set. -/
def Valid {m : ℕ} (c : Cell m) : Prop :=
  (∀ i, |c.1 i| ≤ 1) ∧ selected c ⊆ active c

/-- The active set contains precisely the positively assigned records. -/
def active {m : ℕ} (c : Cell m) : Finset (Fin m) :=
  Finset.univ.filter (fun i => c.2.1 i = true)

/-- The conditional order-d energy at a fixed cell count is the mean, under the cell law at that count, of the order-d subset energy at tilt τ. -/
def conditionalEnergy (ν : ∀ m, Measure (Cell m)) (τ : ℝ) (m d : ℕ) : ℝ :=
  ∫ c, subsetEnergy τ c d ∂ν m

/-- The posterior denominator is the sum of the likelihoods at the two latent signs. -/
def denominator {m : ℕ} (τ : ℝ) (c : Cell m) : ℝ :=
  signLikelihood τ c 1 + signLikelihood τ c (-1)

/-- The cell overlap series starts at one and sums all positive-order coefficient terms. -/
def overlapSeries (t : ℕ → ℝ) (z : ℝ) : ℝ :=
  1 + ∑' d : ℕ, t (d + 1) * z ^ (d + 1)

/-- The selected set contains precisely the records retained by the selection flags. -/
def selected {m : ℕ} (c : Cell m) : Finset (Fin m) :=
  Finset.univ.filter (fun i => c.2.2 i = true)

/-- The sign likelihood at a latent sign ℓ is the product over all records of 1 + τ · ℓ · uᵢ · sᵢ, where uᵢ is the record's score and sᵢ = ±1 its assignment sign. -/
def signLikelihood {m : ℕ} (τ : ℝ) (c : Cell m) (ell : ℝ) : ℝ :=
  ∏ i, (1 + τ * ell * c.1 i * sign (c.2.1 i))

/-- The order-d energy sums squared posterior coefficients over selected subsets of size d. -/
def subsetEnergy {m : ℕ} (τ : ℝ) (c : Cell m) (d : ℕ) : ℝ :=
  ∑ S ∈ (selected c).powersetCard d, (posterior τ c S) ^ 2

