/-- Given [a real sampling law](hyp:μ) and [a finite sample size](hyp:n), the [iid sample law](goal) is [the corresponding finite product measure](step:1). -/
def iidSample (μ : Measure ℝ) (n : ℕ) : Measure (Fin n → ℝ) :=
  Measure.pi fun _ : Fin n => μ

/-- Given [a finite dimension](hyp:n), [an ordered real tuple](hyp:y), and [a coordinate index](hyp:i), the [ordered spacing](goal) is [the successive difference at that coordinate, beginning from zero](step:1). -/
def orderedSpacings (n : ℕ) (y : Fin n → ℝ) (i : Fin n) : ℝ :=
  if i.val = 0 then y i else y i - y ⟨i.val - 1, by omega⟩

/-- Given [a finite dimension](hyp:n), the [linear spacing transformation](goal) is [the linear map of successive coordinate differences](step:1). -/
def orderedSpacingsLinear (n : ℕ) : (Fin n → ℝ) →ₗ[ℝ] (Fin n → ℝ) :=
  LinearMap.pi fun i : Fin n =>
    if h : i.val = 0 then (LinearMap.proj i : (Fin n → ℝ) →ₗ[ℝ] ℝ)
    else (LinearMap.proj i : (Fin n → ℝ) →ₗ[ℝ] ℝ) -
      LinearMap.proj (⟨i.val - 1, by omega⟩ : Fin n)

/-- Given [a finite dimension](hyp:n), the [ordered unit region](goal) is [the nondecreasing part of the closed unit cube](step:1). -/
def orderedUnitRegion (n : ℕ) : Set (Fin n → ℝ) :=
  {x | (∀ i, x i ∈ Set.Icc (0 : ℝ) 1) ∧ Monotone x}

/-- Given [a finite dimension](hyp:n), [a spacing vector](hyp:z), and [a coordinate index](hyp:i), the [prefix coordinate](goal) is [the sum of spacings through that coordinate](step:1). -/
def prefixCoordinates (n : ℕ) (z : Fin n → ℝ) (i : Fin n) : ℝ :=
  ∑ j ∈ Finset.Iic i, z j

/-- Given [a finite dimension](hyp:n) and [a real radius](hyp:r), the [scaled spacing simplex](goal) is [the nonnegative coordinate simplex with total at most that radius](step:1). -/
def scaledSpacingSimplex (n : ℕ) (r : ℝ) : Set (Fin n → ℝ) :=
  {z | (∀ i, 0 ≤ z i) ∧ (∑ i, z i) ≤ r}

/-- Given [a finite sample size](hyp:n) and [a real tuple](hyp:x), the [sorted sample](goal) is [that tuple rearranged in nondecreasing order](step:1). -/
def sortedSample (n : ℕ) (x : Fin n → ℝ) : Fin n → ℝ :=
  x ∘ Tuple.sort x

/-- Given [a finite dimension](hyp:n), the [spacing simplex](goal) is [the nonnegative coordinate simplex with total at most one](step:1). -/
def spacingSimplex (n : ℕ) : Set (Fin n → ℝ) :=
  {z | (∀ i, 0 ≤ z i) ∧ (∑ i, z i) ≤ 1}

/-- Given [a finite dimension](hyp:n), the [unit cube](goal) is [the set of real tuples with every coordinate in the closed unit interval](step:1). -/
def unitCube (n : ℕ) : Set (Fin n → ℝ) :=
  {x | ∀ i, x i ∈ Set.Icc (0 : ℝ) 1}

/-- A [privacy level](hyp:ε) and [Boolean input sign](hyp:b) determine [the
probability of a positive randomized-response report](goal), equal to
[`exp ε/(exp ε + 1)` for positive input and `1/(exp ε + 1)` for negative input](step:1). -/
def responseProbability (ε : ℝ) (b : Bool) : ℝ :=
  if b then Real.exp ε / (Real.exp ε + 1)
  else 1 / (Real.exp ε + 1)

/-- Setwise local privacy bounds every row measure by `r` times every other row measure. -/
def SetwisePrivate (Q : Kernel (Fin 4) Z) (r : ℝ) : Prop :=
  ∀ i j s, MeasurableSet s → Q i s ≤ ENNReal.ofReal r * Q j s

/-- Normalize a privacy-cone vector to a cube coordinate: the coordinate divided by the least
coordinate, minus one, all divided by `r - 1`; the value is zero whenever the least coordinate
is zero, which for a vector in the cone happens only at the zero vector. The formula is
evaluated for arbitrary real vectors as well. -/
def coneCubeCoord (r : ℝ) (f : Fin 4 → ℝ) (i : Fin 4) : ℝ :=
  if coneBase f = 0 then 0 else (f i / coneBase f - 1) / (r - 1)

