/-- Project a finite-dimensional input score onto one real direction. -/
def projectedScore {d : ℕ} (u : Fin 4 → Fin d → ℝ) (v : Fin d → ℝ) (i : Fin 4) : ℝ :=
  ∑ k, v k * u i k

/-- The staircase pattern equals `r` on its indexing subset and one elsewhere. -/
def ray (r : ℝ) (S : RayIndex) (i : Fin 4) : ℝ :=
  if i ∈ S.val then r else 1

/-- The mixture mass of a finite release atom under input probabilities `p`. -/
def releaseMass (T : Kernel (Fin 4) RayIndex) (p : Fin 4 → ℝ) (S : RayIndex) : ℝ :=
  ∑ i, p i * (T i {S}).toReal

/-- The projected score of an active finite release atom under input probabilities `p`. -/
def releaseScore (T : Kernel (Fin 4) RayIndex) (p u : Fin 4 → ℝ) (S : RayIndex) : ℝ :=
  (∑ i, p i * (T i {S}).toReal * u i) / releaseMass T p S

/-- The real Radon–Nikodym density of one row relative to the row sum. -/
def rowDensity (Q : Kernel (Fin 4) Z) (i : Fin 4) (z : Z) : ℝ :=
  ((Q i).rnDeriv (rowSum Q) z).toReal

/-- The sum of the four row measures is a finite common dominating measure. -/
def rowSum (Q : Kernel (Fin 4) Z) : Measure Z :=
  ∑ i : Fin 4, Q i

/-- For [a real scale parameter](hyp:b) and [a real evaluation point](hyp:x), the [centered
Laplace density](goal) is $(2b)^{-1}\exp(-|x|/b)$. -/
def laplacePDF (b x : ℝ) : ℝ := (2 * b)⁻¹ * Real.exp (-|x| / b)

/-- For [a measure on the real line](hyp:ρ) (a population probability law in the results using
it) and [a deviation radius](hyp:radius), [the fixed-size bad set](goal)
is [the set of vectors whose uniform empirical-CDF deviation exceeds that radius](step:1). -/
def fixedCDFBadSet {m : ℕ} (ρ : Measure ℝ) (radius : ℝ) : Set (Fin m → ℝ) :=
  {x | uniformCDFDeviation ρ x > radius}

/-- For [a marked sample](hyp:Z) and [a Boolean word](hyp:w), [the exact-word event](goal)
is [the set of outcomes whose complete mark vector equals that word](step:1). -/
def wordEvent {Ω : Type*} {n : ℕ} (Z : Fin n → Ω → Bool × ℝ)
    (w : Fin n → Bool) : Set Ω :=
  {ω | ∀ i, (Z i ω).1 = w i}

/-- For [a population law](hyp:ρ) and [a deviation threshold](hyp:ε),
[the lower one-sided empirical-CDF bad set contains the sample vectors whose lower deviation is
greater than that threshold](goal). -/
def lowerCDFBadSet {n : ℕ} (ρ : Measure ℝ) (ε : ℝ) : Set (Fin n → ℝ) :=
  {x | lowerCDFDeviation ρ x > ε}

/-- For [a population law](hyp:ρ) and [a deviation threshold](hyp:ε),
[the upper one-sided empirical-CDF bad set contains the sample vectors whose upper deviation is
greater than that threshold](goal). -/
def upperCDFBadSet {n : ℕ} (ρ : Measure ℝ) (ε : ℝ) : Set (Fin n → ℝ) :=
  {x | upperCDFDeviation ρ x > ε}

/-- [Two fine cells](hyp:a,b) are [equal or adjacent on the path](goal). -/
def Adjacent {K : ℕ} (a b : Fin K) : Prop :=
  a.val ≤ b.val + 1 ∧ b.val ≤ a.val + 1

/-- [An assignment to a finite labelled set](hyp:x) has [connected occupied cells](goal). -/
noncomputable def ConnectedAssignment {ι : Type*} [Fintype ι] {K : ℕ}
    (x : ι → Fin K) : Prop := PathConnected (Finset.univ.image x)

/-- [Interval clipping](goal) of [a real estimate t](hyp:t) at [radius R](hyp:R) is
max(−R, min(R, t)); for nonnegative R this confines t to the symmetric interval from −R to R. -/
def clip (R t : ℝ) : ℝ := max (-R) (min R t)

/-- [The uniform Gram lower-tail constant](goal) at [overlap margin ε](hyp:epsilon) is the
reciprocal of twice the squared good-design threshold, 1/(2·(ε(1 − ε)/8)²). -/
def gramTailConstant (epsilon : ℝ) : ℝ := 1 / (2 * gramThreshold epsilon ^ 2)

/-- [The label fiber](goal) of [a vector x of n cell labels](hyp:n,x) is the set of designs of n
cell-treatment pairs whose cell coordinates equal x. -/
def labelFiber {n : ℕ} (x : Fin n → κ) : Set (Fin n → κ × Bool) :=
  {d | ∀ i, (d i).1 = x i}

